create table if not exists public.products (id uuid primary key default gen_random_uuid(), category text not null, name text not null, description text default '', price numeric(12,2) default 0, image_url text default '', active boolean default true, created_at timestamptz default now());
create table if not exists public.projects (id uuid primary key default gen_random_uuid(), name text not null, description text default '', image_url text default '', active boolean default true, created_at timestamptz default now());